data.query:
query Count($where: CountWhereInput, $orderBy: [CountOrderByInput!], $first: Int, $after: String) {
  count(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        blind
        externalId
        scheduledStartAt
        actualStartAt
        completedAt
        customData
        integrationData
        countStatusId
        countParameters{
          edges{
            node{
              productId
              productCategoryId
              storageUnitId
              storageZoneId
              areaId         
            }
          }
        }
      }
    }
  }
}

query Inventory($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    pageInfo{ hasNextPage endCursor }
    edges {
      node {
        id
        productId
        product{
          code
        }
        storageUnitId
        quantity{ value unitId }
        grossWeight{ value unitId }
      }
    }
  }
}

data.variablesTransform:
{
  "payload": inventory.edges.node.{
    "create":{
      "inventoryId": id,
      "storageUnitId": storageUnitId,
      "quantity": quantity,
      "weight": grossWeight,
      "countLineId": $join([
        $state.context.QUERY.count.edges.node.id,
        productId,
        storageUnitId
      ], "::")
    }
  }
}

data.responseTransform:
{
  "error": true,
  "message": "The count has not been started."
}

